import{_ as i,a0 as l,w as o,s as d,I as n,x as a,a1 as e,A as p,ao as h}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"使用 Python 处理 JSON 格式的数据 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Python 处理 JSON 格式的数据 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Python 处理 JSON 格式的数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Python 处理 JSON 格式的数据 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190716 Save and load Python data with JSON","title":"使用 Python 处理 JSON 格式的数据","tag":"201907","desc":""},"relativePath":"201907/20190716 Save and load Python data with JSON.md","filePath":"[post].md"}'),r={name:"201907/20190716 Save and load Python data with JSON.md"};function u(c,s,b,g,k,m){const t=l("Link");return o(),d("div",null,[s[19]||(s[19]=n("h1",{id:"使用-python-处理-json-格式的数据",tabindex:"-1"},[a("使用 Python 处理 JSON 格式的数据 "),n("a",{class:"header-anchor",href:"#使用-python-处理-json-格式的数据","aria-label":"Permalink to “使用 Python 处理 JSON 格式的数据”"},"​")],-1)),s[20]||(s[20]=n("blockquote",null,[n("p",null,"如果你不希望从头开始创造一种数据格式来存放数据，JSON 是一个很好的选择。如果你对 Python 有所了解，就更加事半功倍了。下面就来介绍一下如何使用 Python 处理 JSON 数据。")],-1)),s[21]||(s[21]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bus_cloud_database.png?itok=lhhU42fg",alt:"Cloud and databsae incons",title:"Cloud and databsae incons"})],-1)),n("p",null,[e(t,{href:"https://json.org"},{default:p(()=>[...s[0]||(s[0]=[a("JSON",-1)])]),_:1}),s[1]||(s[1]=a(" 的全称是 ",-1)),s[2]||(s[2]=n("ruby",null,[a("JavaScript 对象表示法"),n("rt",null,"JavaScript Object Notation")],-1)),s[3]||(s[3]=a("。这是一种以键值对的形式存储数据的格式，并且很容易解析，因而成为了一种被广泛使用的数据格式。另外，不要因为 JSON 名称而望文生义，JSON 并不仅仅在 JavaScript 中使用，它也可以在其它语言中使用。下文会介绍它是如何在 Python 中使用的。",-1))]),s[22]||(s[22]=h(`<p>首先我们给出一个 JSON 示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;:&quot;tux&quot;,</span></span>
<span class="line"><span>    &quot;health&quot;:&quot;23&quot;,</span></span>
<span class="line"><span>    &quot;level&quot;:&quot;4&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面是一个和编程语言无关的原生 JSON 数据。熟悉 Python 的人会看出来这个 JSON 数据跟 Python 中的<ruby>字典<rt>dictionary</rt></ruby>长得很像。而这两者之间确实非常相似，如果你对 Python 中的列表和字典数据结构有一定的理解，那么 JSON 理解起来也不难。</p><h3 id="使用字典存放数据" tabindex="-1">使用字典存放数据 <a class="header-anchor" href="#使用字典存放数据" aria-label="Permalink to “使用字典存放数据”">​</a></h3><p>如果你的应用需要存储一些结构复杂的数据，不妨考虑使用 JSON 格式。对比你可能曾经用过的自定义格式的文本配置文件，JSON 提供了更加结构化的可递归的存储格式。同时，Python 自带的 <code>json</code> 模块已经提供了可以将 JSON 数据导入/导出应用时所需的所有解析库。因此，你不需要针对 JSON 自行编写代码进行解析，而其他开发人员在与你的应用进行数据交互的时候也不需要去解析新的数据格式。正是这个原因，JSON 在数据交换时被广泛地采用了。</p><p>以下是一段在 Python 中使用嵌套字典的代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env python3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import json</span></span>
<span class="line"><span></span></span>
<span class="line"><span># instantiate an empty dict</span></span>
<span class="line"><span>team = {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># add a team member</span></span>
<span class="line"><span>team[&#39;tux&#39;] = {&#39;health&#39;: 23, &#39;level&#39;: 4}</span></span>
<span class="line"><span>team[&#39;beastie&#39;] = {&#39;health&#39;: 13, &#39;level&#39;: 6}</span></span>
<span class="line"><span>team[&#39;konqi&#39;] = {&#39;health&#39;: 18, &#39;level&#39;: 7}</span></span></code></pre></div><p>这段代码声明了一个名为 <code>team</code> 的字典，并初始化为一个空字典。</p><p>如果要给这个字典添加内容，首先需要创建一个键，例如上面示例中的 <code>tux</code>、<code>beastie</code>、<code>konqi</code>，然后为这些键一一提供对应的值。上面示例中的值由一个个包含游戏玩家信息的字典充当。</p><p>字典是一种可变的变量。字典中的数据可以随时添加、删除或更新。这样的特性使得字典成为了应用程序存储数据的极好选择。</p><h3 id="使用-json-格式存储数据" tabindex="-1">使用 JSON 格式存储数据 <a class="header-anchor" href="#使用-json-格式存储数据" aria-label="Permalink to “使用 JSON 格式存储数据”">​</a></h3><p>如果存放在字典中的数据需要持久存储，这些数据就需要写到文件当中。这个时候就需要用到 Python 中的 <code>json</code> 模块了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(&#39;mydata.json&#39;, &#39;w&#39;) as f:</span></span>
<span class="line"><span>    json.dump(team, f)</span></span></code></pre></div><p>上面的代码首先创建了一个名为 <code>mydata.json</code> 的文件，然后以写模式打开了这个文件，这个被打开的文件以变量 <code>f</code> 表示（当然也可以用任何你喜欢的名称，例如 <code>file</code>、<code>output</code> 等）。而 <code>json</code> 模块中的 <code>dump()</code> 方法则是用于将一个字典输出到一个文件中。</p><p>从应用中导出数据就是这么简单，同时这些导出的数据是结构化的、可理解的。现在可以查看导出的数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat mydata.json</span></span>
<span class="line"><span>{&quot;tux&quot;: {&quot;health&quot;: 23, &quot;level&quot;: 4}, &quot;beastie&quot;: {&quot;health&quot;: 13, &quot;level&quot;: 6}, &quot;konqi&quot;: {&quot;health&quot;: 18, &quot;level&quot;: 7}}</span></span></code></pre></div><h3 id="从-json-文件中读取数据" tabindex="-1">从 JSON 文件中读取数据 <a class="header-anchor" href="#从-json-文件中读取数据" aria-label="Permalink to “从 JSON 文件中读取数据”">​</a></h3><p>如果已经将数据以 JSON 格式导出到文件中了，也有可能需要将这些数据读回到应用中去。这个时候，可以使用 Python <code>json</code> 模块中的 <code>load()</code> 方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env python3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>f = open(&#39;mydata.json&#39;)</span></span>
<span class="line"><span>team = json.load(f)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(team[&#39;tux&#39;])</span></span>
<span class="line"><span>print(team[&#39;tux&#39;][&#39;health&#39;])</span></span>
<span class="line"><span>print(team[&#39;tux&#39;][&#39;level&#39;])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(team[&#39;beastie&#39;])</span></span>
<span class="line"><span>print(team[&#39;beastie&#39;][&#39;health&#39;])</span></span>
<span class="line"><span>print(team[&#39;beastie&#39;][&#39;level&#39;])</span></span>
<span class="line"><span></span></span>
<span class="line"><span># when finished, close the file</span></span>
<span class="line"><span>f.close()</span></span></code></pre></div><p>这个方法实现了和保存文件大致相反的操作。使用一个变量 <code>f</code> 来表示打开了的文件，然后使用 <code>json</code> 模块中的 <code>load()</code> 方法读取文件中的数据并存放到 <code>team</code> 变量中。</p><p>其中的 <code>print()</code> 展示了如何查看读取到的数据。在过于复杂的字典中迭代调用字典键的时候有可能会稍微转不过弯来，但只要熟悉整个数据的结构，就可以慢慢摸索出其中的逻辑。</p><p>当然，这里使用 <code>print()</code> 的方式太不灵活了。你可以将其改写成使用 <code>for</code> 循环的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in team.values():</span></span>
<span class="line"><span>    print(i)</span></span></code></pre></div><h3 id="使用-json" tabindex="-1">使用 JSON <a class="header-anchor" href="#使用-json" aria-label="Permalink to “使用 JSON”">​</a></h3><p>如上所述，在 Python 中可以很轻松地处理 JSON 数据。因此只要你的数据符合 JSON 的模式，就可以选择使用 JSON。JSON 非常灵活易用，下次使用 Python 的时候不妨尝试一下。</p><hr>`,26)),n("p",null,[s[5]||(s[5]=a("via: ",-1)),e(t,{href:"https://opensource.com/article/19/7/save-and-load-data-python-json"},{default:p(()=>[...s[4]||(s[4]=[a("https://opensource.com/article/19/7/save-and-load-data-python-json",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("作者：",-1)),e(t,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[6]||(s[6]=[a("Seth Kenlon",-1)])]),_:1}),s[11]||(s[11]=a(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),e(t,{href:"https://github.com/HankChow"},{default:p(()=>[...s[8]||(s[8]=[a("HankChow",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:p(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const N=i(r,[["render",u]]);export{S as __pageData,N as default};
